    img: Image.Image,
    error_code: str,
    allowed_mimetypes: Collection[str] = MIME_TYPE_TO_PIL_IDENTIFIER,
):
    image_mimetype = PIL_IDENTIFIER_TO_MIME_TYPE.get(img.format) if img.format else None
